<script setup lang="ts">import { AlertTriangle, Bot, CloudSun, Database, FileText, Users } from 'lucide-vue-next'; definePageMeta({layout:'admin',middleware:'admin-auth'}); useSeoMeta({title:'Administración'}); const {request}=useApi(); const stats=ref<any>({}); const jobs=ref<any[]>([]); onMounted(async()=>{try{[stats.value,jobs.value]=await Promise.all([request('/admin/summary'),request('/admin/jobs',{query:{limit:10}})])}catch{}}); const cards=computed(()=>[{label:'Estaciones activas',value:stats.value.stations_active||0,icon:CloudSun},{label:'Usuarios activos',value:stats.value.users_active||0,icon:Users},{label:'Lecturas',value:stats.value.readings_total||0,icon:Database},{label:'Alertas 72 h',value:stats.value.alerts_72h||0,icon:AlertTriangle},{label:'Agentes activos',value:stats.value.agents_active||0,icon:Bot},{label:'Reportes',value:stats.value.reports_total||0,icon:FileText}])</script>
<template><section><AdminPageHeader title="Panel administrativo" description="Resumen operativo, calidad de datos y trabajos en segundo plano."/><div class="grid grid-3"><article v-for="card in cards" :key="card.label" class="card stat"><component :is="card.icon"/><div><b>{{card.value}}</b><span>{{card.label}}</span></div></article></div><div class="grid grid-2 admin-sections"><article class="card"><div class="card-body"><h2 class="section-title">Trabajos recientes</h2><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Estado</th><th>Creado</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td>{{job.job_type}}</td><td><span class="badge" :class="job.status==='COMPLETED'?'badge-success':job.status==='FAILED'?'badge-danger':'badge-warning'">{{job.status}}</span></td><td>{{new Date(job.created_at).toLocaleString('es-PY')}}</td></tr><tr v-if="!jobs.length"><td colspan="3">Sin trabajos recientes.</td></tr></tbody></table></div></div></article><article class="card"><div class="card-body"><h2 class="section-title">Puesta en marcha</h2><ol><li>Configure la llave FECOCLIMA como secreto del backend.</li><li>Pruebe la conexión de Raul Peña.</li><li>Sincronice datos y revise variables faltantes.</li><li>Registre parcelas y ciclos con fecha de siembra.</li><li>Valide técnicamente reglas pendientes antes de publicarlas.</li></ol><div class="notice notice-warning">La ausencia de sensores de suelo u hoja genera “Datos insuficientes” cuando son obligatorios. El sistema no completa esos valores artificialmente.</div></div></article></div></section></template>
<style scoped>.stat{display:flex;align-items:center;gap:15px;padding:20px}.stat>svg{width:38px;height:38px;padding:8px;color:#fff;background:var(--fc-primary);border-radius:12px}.stat b,.stat span{display:block}.stat b{font-size:1.7rem;color:var(--fc-primary)}.stat span{color:var(--fc-text-muted);font-size:.85rem}.admin-sections{margin-top:22px}li{margin-bottom:10px}</style>
